import { Injectable } from '@angular/core';

@Injectable({
  providedIn: 'root'
})
export class MyService {
  constructor() { }
}

import { Injectable } from '@angular/core';

@Injectable({
  providedIn: 'root'
})
export class LoggerService {
  log(message: string) {
    console.log(`[LOG]: ${message}`);
  }

  error(message: string) {
    console.error(`[ERROR]: ${message}`);
  }
}

slides.content:
Before Angular 6, services were registered in the `providers` array of an `NgModule`:

```typescript
@NgModule({
  providers: [LoggerService]
})
```

Now, the recommended way is to use `providedIn` inside `@Injectable()`. This enables **tree‑shaking** – if no one injects the service, it’s removed from the final bundle automatically.
